<div class="row justify-content-center"><div class="col-xl-8"><div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0"><?= html_escape($page_title) ?></h2></div><div class="card-body"><?php if ($form_error): ?><div class="alert alert-danger" role="alert"><?= html_escape($form_error) ?></div><?php endif; ?><?= validation_errors('<div class="alert alert-danger" role="alert">', '</div>') ?><?= form_open(current_url(), array('novalidate' => 'novalidate')) ?><div class="row g-3"><div class="col-md-5"><label class="form-label" for="crew_code">Crew code *</label><input class="form-control text-uppercase" id="crew_code" name="crew_code" maxlength="50" value="<?= set_value('crew_code', $crew->crew_code ?? '') ?>" required></div><div class="col-md-7"><label class="form-label" for="crew_name">Crew name</label><input class="form-control" id="crew_name" name="crew_name" maxlength="200" value="<?= set_value('crew_name', $crew->crew_name ?? '') ?>"></div><div class="col-12"><label class="form-label" for="source_trade">Source trade *</label><input class="form-control" id="source_trade" name="source_trade" maxlength="100" value="<?= set_value('source_trade', $crew->source_trade ?? '') ?>" required></div></div><?php $active_default = $this->input->method(TRUE) !== 'POST' && ($crew === NULL || (bool) $crew->is_active); ?><div class="form-check my-4"><input class="form-check-input" type="checkbox" id="is_active" name="is_active" value="1" <?= set_checkbox('is_active', '1', $active_default) ?>><label class="form-check-label" for="is_active">Active</label></div><?php if ($crew): ?><p class="small text-body-secondary">Created <?= html_escape(date('d-M-Y h:i A', strtotime($crew->created_at))) ?> · Updated <?= html_escape(date('d-M-Y h:i A', strtotime($crew->updated_at))) ?></p><?php endif; ?><button class="btn btn-primary" type="submit">Save Crew</button> <a class="btn btn-outline-secondary" href="<?= $crew ? site_url('crews/'.$crew->crew_id) : site_url('crews') ?>"